import{z as l,x as n,o as t,c as D,q as r,j as A,D as E,d as e,s as i,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"TD(0) 与自举","description":"","frontmatter":{"title":"TD(0) 与自举","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/td-zero-bootstrapping.md","filePath":"llm/td-zero-bootstrapping.md","lastUpdated":1791413859000}'),p={name:"llm/td-zero-bootstrapping.md"};function d(_,a,m,T,C,c){const s=n("Mermaid");return t(),D("div",null,[a[2]||(a[2]=r('<h1 id="td-0-与自举" tabindex="-1">TD(0) 与自举 <a class="header-anchor" href="#td-0-与自举" aria-label="Permalink to &quot;TD(0) 与自举&quot;">​</a></h1><div class="epigraph"><p>用自己还没兑现的估计当真值，一步一学；偏差是自举收的学费，换来的是不等大结局。</p><footer>—— 据 Sutton, Learning to Predict by the Methods of Temporal Differences, 1988；Sutton &amp; Barto, 2018, 第 6 章整理</footer></div><p><a href="/llm/monte-carlo-evaluation">上一课</a>把无模型评估落在经验回报的平均上：无偏、高方差、必须等回合跑完。缺口跟着「等」字来：回合很长、终止很远、甚至没有终止时，蒙特卡洛一步也学不动；走了一半才发现方向不对，前面几百步的采样白费。本课写 TD(0)：每走一步就用当前估计造一个目标、立即更新，不等大结局。后面的 SARSA、Q 学习与致命三要素，都建立在这套自举语法上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>蒙特卡洛的目标 \\(G_t\\) 在回合结束前不存在。TD(0) 把目标换成一个立刻可得的东西：\\(r_{t+1}+\\gamma V(s_{t+1})\\)。第一项是刚到手的真实奖励，第二项是当前估计——<strong>用估计替换期望里还不知道的余下部分</strong>，这一步叫自举。若 \\(V\\) 已经是 \\(v_\\pi\\)，目标在期望上恰好对齐：\\(\\mathbb{E}_\\pi[r_{t+1}+\\gamma V(s_{t+1})\\mid s_t]=v_\\pi(s_t)\\)；\\(V\\) 不准时，目标是「当前认知下的 \\(v_\\pi\\)」，学习变成追赶自己的影子。自举因此先天地带偏：估计进了目标，误差就有机会被当成信号学回去。<span class="marginnote">自举可以类比接力猜数：不等谜底揭晓，直接拿自己当前的猜测当中间答案先往前传。猜测立刻可用，但猜错的部分会顺着链条传下去——这就是「用估计估估计」要交的学费。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>更新式只有一行：</p> \\[V(s_t)\\leftarrow V(s_t)+\\alpha\\big[\\,r_{t+1}+\\gamma V(s_{t+1})-V(s_t)\\,\\big] \\]<p>方括号里是 TD 误差 \\(\\delta_t\\)：现实与预期之差。本课钉两点。一，\\(\\delta_t\\) 不是噪声而是学习信号：它同时读出「这条转移带来多少惊喜」与「\\(V(s_t)\\) 错了多少」，后面的优势估计与 critic 回归用的都是它。二，终止状态钉死 \\(V=0\\)：若 \\(s_{t+1}\\) 终止，目标只剩 \\(r_{t+1}\\)；这条约定忘了，终止状态自己也会被更新，\\(\\delta\\) 永远拖着一项假的。算法在线运行：一步、一状态、一次更新，内存 \\(O(1)\\)，回合中途就在学。<span class="marginnote">给个数字实例：\\(\\alpha=0.1\\)，\\(V(s_t)=5\\)，实际拿到 \\(r=1\\)、\\(\\gamma=0.9\\)、\\(V(s_{t+1})=6\\)，则 \\(\\delta=1+0.9\\times6-5=1.4\\)，更新后 \\(V(s_t)=5+0.1\\times1.4=5.14\\)——一步只挪一成的差距，稳但不猛。</span><span class="marginnote">初学者最容易忘「终止状态 \\(V\\) 恒为 0」。忘了它，终止状态也会被更新出非零价值，\\(\\delta\\) 里永远拖着一笔假账，整条链的价值系统性虚高——这是 TD 实现里最常见的一行 bug。</span></p>',9)),(t(),A(o,null,{default:E(()=>[i(s,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E5%8F%96%E5%BE%97%E8%BD%AC%E7%A7%BB%20(s_t%2C%20a_t%2C%20r%2C%20s_t%2B1)%22%5D%20--%3E%20DELTA%5B%22%CE%B4%20%3D%20r%20%2B%20%CE%B3V(s_t%2B1)%20%E2%88%92%20V(s_t)%22%5D%0A%20%20DELTA%20--%3E%20UPD%5B%22V(s_t)%20%E5%8A%A0%E4%B8%8A%20%CE%B1%C2%B7%CE%B4%22%5D%0A%20%20UPD%20--%3E%20NEXT%5B%22%E8%B5%B0%E8%BF%9B%20s_t%2B1%EF%BC%8C%E9%87%8D%E5%A4%8D%22%5D%0A%20%20DELTA%20--%3E%20READ%7B%22%CE%B4%20%E7%9A%84%E4%B8%A4%E7%A7%8D%E8%AF%BB%E6%B3%95%22%7D%0A%20%20READ%20--%3E%20A%5B%22%E6%83%8A%E5%96%9C%EF%BC%9A%E8%BD%AC%E7%A7%BB%E8%B6%85%E5%87%BA%E9%A2%84%E6%9C%9F%E5%A4%9A%E5%B0%91%22%5D%0A%20%20READ%20--%3E%20B%5B%22%E7%BA%A0%E9%94%99%EF%BC%9A%E6%97%A7%E4%BC%B0%E8%AE%A1%E5%B7%AE%E5%9C%A8%E5%93%AA%E9%87%8C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"偏差-方差账本。目标含 \\(V(s_{t+1})\\)：\\(V\\) 不准，目标就偏，且自举把误差沿状态链传播——一个高估的格子会通过目标抬高它的前驱。但目标只含一步的真实随机性：蒙特卡洛目标的方差随余下回合长度增长，TD 目标只有一步抽样加一层旧估计的误差，通常小得多。收敛账在表格与固定策略下成立：步长按 Robbins–Monro 条件衰减时，TD(0) 收敛到 \\(v_\\pi\\)（Sutton 1988；Tsitsiklis & Van Roy 1997 给出一般分析）。账本之外还有适用面：持续任务没有终止，蒙特卡洛干脆无定义，TD 照跑；样本效率上，每条转移被立刻用掉一次，不必攒到回合末。",-1)),(t(),A(o,null,{default:E(()=>[i(s,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20TD%0A%20%20MC%5B%22%E8%92%99%E7%89%B9%E5%8D%A1%E6%B4%9B%E7%9B%AE%E6%A0%87%20G_t%EF%BC%9A%E7%AD%89%E5%9B%9E%E5%90%88%E6%9C%AB%E6%89%8D%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20S1%5B%22%E6%95%B4%E6%9D%A1%E4%BD%99%E4%B8%8B%E5%9B%9E%E6%8A%A5%E9%83%BD%E6%98%AF%E7%9C%9F%E5%AE%9E%E9%87%87%E6%A0%B7%EF%BC%9A%E6%97%A0%E5%81%8F%22%5D%0A%20%20S1%20--%3E%20V1%5B%22%E6%96%B9%E5%B7%AE%E9%9A%8F%E4%BD%99%E4%B8%8B%E5%9B%9E%E5%90%88%E9%95%BF%E5%BA%A6%E5%A2%9E%E9%95%BF%22%5D%0A%20%20MC%20--%3E%20W%5B%22%E5%9B%9E%E5%90%88%E9%95%BF%E6%88%96%E6%97%A0%E7%BB%88%E6%AD%A2%EF%BC%9A%E4%B8%80%E6%AD%A5%E4%B9%9F%E5%AD%A6%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20TD%5B%22TD%20%E7%9B%AE%E6%A0%87%20r%20%2B%20%CE%B3V(s')%EF%BC%9A%E8%B5%B0%E4%B8%80%E6%AD%A5%E5%B0%B1%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20S2%5B%22%E5%8F%AA%E6%9C%89%E4%B8%80%E6%AD%A5%E7%9C%9F%E5%AE%9E%E9%87%87%E6%A0%B7%EF%BC%9A%E5%B8%A6%E4%B8%80%E5%B1%82%E6%97%A7%E4%BC%B0%E8%AE%A1%E7%9A%84%E5%81%8F%22%5D%0A%20%20S2%20--%3E%20V2%5B%22%E6%96%B9%E5%B7%AE%E5%B0%8F%EF%BC%8C%E4%BD%86%E8%AF%AF%E5%B7%AE%E6%B2%BF%E7%8A%B6%E6%80%81%E9%93%BE%E4%BC%A0%E6%92%AD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">这张图回答的问题是：偏差与方差各自从哪来。蒙特卡洛的「干净」是用等待买的——所有随机性都真实兑现，所以无偏也高方差；TD 用一层旧估计替换掉余下全部随机性，方差立刻变小，代价是旧估计的偏被写进目标。</span></p><p><span class="marginnote">Sutton 1988 的原文把监督学习、蒙特卡洛与 TD 放进同一个预测框架：TD 目标是「当前估计下的期望的样本」——这也是后来一切 critic 回归 \\(r+\\gamma V(s&#39;)\\) 的出处。</span></p><p>初值的角色变了：蒙特卡洛目标无偏，从哪个 \\(V\\) 起步只影响速度；TD 目标带着旧估计，初值差会拖着收敛路径走一段弯路。这不是实现瑕疵，是自举的结构性代价——本课程后面讲致命三要素时会看到，同一结构在函数逼近与离策略加入后走得更远。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>偏差不免费：学到的 \\(V\\) 会先系统性偏离再爬回来，步长与初值决定路径形状。TD(0) 只取一步：一步目标与完全蒙特卡洛之间是 n 步与 TD(λ) 的连续谱，本课程到 actor-critic 一带才需要中间档，现在只钉两端。深度 RLHF 里 critic 每步回归 \\(r+\\gamma V_\\psi(s&#39;)\\) 正是这套目标；它的稳定性问题——目标随参数动、误差沿链放大——要到函数逼近与离策略凑齐时才升级成定理级警告，此处先记下结构。TD(0) 评估的是给定策略，控制的半步还缺着：下一课把自举搬到 \\((s,a)\\) 上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TD(0) 用 \\(r_{t+1}+\\gamma V(s_{t+1})\\) 当目标，每步更新；自举即用估计估估计。</li><li>TD 误差 \\(\\delta_t\\) 是学习信号：一步惊喜与估计纠错二合一。</li><li>偏差换方差：目标带旧估计的偏，但只含一步真实随机性；在线、省样本、可用于持续任务。</li><li>表格、固定策略、衰减步长下收敛到 \\(v_\\pi\\)；初值影响路径，误差沿链传播。</li><li>终止状态价值钉死为零，否则 \\(\\delta\\) 永远带假项。</li><li>出处：Sutton, Learning to Predict by the Methods of Temporal Differences, Machine Learning, 1988；Sutton &amp; Barto 2018 第 6 章；Tsitsiklis &amp; Van Roy 1997。</li></ul>',7))])}const u=l(p,[["render",d]]);export{h as __pageData,u as default};
